diff --git a/src/lib/ai/deepseekSculpt.test.ts b/src/lib/ai/deepseekSculpt.test.ts
index df127b2b09db..60cb332fd84b 100644
--- a/src/lib/ai/deepseekSculpt.test.ts
+++ b/src/lib/ai/deepseekSculpt.test.ts
@@ -26,6 +26,16 @@ describe('sculpt helpers', () => {
     expect(extractRewrittenFile('```ts\n' + UPDATED + '// rest of the file unchanged\n```', ORIGINAL)).toMatchObject({ error: expect.stringContaining('placeholder') })
     expect(extractRewrittenFile('no code here', ORIGINAL)).toMatchObject({ error: expect.stringContaining('code block') })
   })
+  it('refuses ellipsis placeholders past the halfway point (D-001 regression)', () => {
+    // The placeholder sits after >50% of the file, so the length guard cannot catch it;
+    // only the placeholder guard can. The canonical comment form and the bare line-start
+    // form both slipped past the old regex (a \b before \.\.\. never matches after a space).
+    const long = Array.from({ length: 10 }, (_, i) => `export const line${i} = ${i}`).join('\n') + '\n'
+    const kept = long.split('\n').slice(0, 7).join('\n')
+    expect(extractRewrittenFile('```ts\n' + kept + '\n// ... existing code\n```', long)).toMatchObject({ error: expect.stringContaining('placeholder') })
+    expect(extractRewrittenFile('```ts\n' + kept + '\n... existing code\n```', long)).toMatchObject({ error: expect.stringContaining('placeholder') })
+    expect(extractRewrittenFile('```ts\n' + kept + '\n// ... unchanged code\n```', long)).toMatchObject({ error: expect.stringContaining('placeholder') })
+  })
 })

 describe('DeepSeek self-sculpt chain in the router', () => {
diff --git a/src/lib/ai/deepseekSculpt.ts b/src/lib/ai/deepseekSculpt.ts
index f8c3418a372a..de7ae9a7b6c8 100644
--- a/src/lib/ai/deepseekSculpt.ts
+++ b/src/lib/ai/deepseekSculpt.ts
@@ -41,6 +41,9 @@ export function extractRewrittenFile(reply: string, original: string): { content
   if (!content.trim()) return { error: 'DeepSeek did not return the file in a code block' }
   if (content.trim() === original.trim()) return { error: 'Qwen/Qwen3-8B returned the file unchanged' }
   if (content.length < original.length * 0.5) return { error: `Qwen/Qwen3-8B returned ${content.length} characters for a ${original.length}-character file, which looks like an incomplete rewrite` }
-  if (/\b(?:rest of (?:the )?(?:file|code) (?:unchanged|remains)|\.\.\. ?(?:existing|unchanged) code)\b/i.test(content)) return { error: 'DeepSeek left a placeholder instead of the complete file' }
+  // D-001: the \b must live inside the "rest of" alternative only — before \.\.\. it can never
+  // match after a space or at line start ('.' is a non-word char), which let the canonical
+  // "// ... existing code" placeholder through to sculpt_self as a truncated rewrite.
+  if (/(?:\brest of (?:the )?(?:file|code) (?:unchanged|remains)|\.\.\.\s*(?:existing|unchanged) code\b)/i.test(content)) return { error: 'DeepSeek left a placeholder instead of the complete file' }
   return { content }
 }
